function updateHud(){if(!game)return;let s=statValues();$('#timer').textContent=fmtTime(game.time);$('#kills').textContent=game.kills;$('#wave').textContent=game.wave;$('#hpText').textContent=`${Math.max(0,Math.ceil(player.hp))} / ${Math.round(s.hp)}`;$('#hpFill').style.width=`${clamp(player.hp/s.hp*100,0,100)}%`;$('#xpText').textContent=`${Math.floor(game.xp)} / ${game.nextXp}`;$('#xpFill').style.width=`${clamp(game.xp/game.nextXp*100,0,100)}%`;$('#level').textContent=game.level;let ult=$('#ultButton');$('#ultCharge').textContent=`${Math.floor(game.charge)}% CHARGED · SPACE`;ult.classList.toggle('ready',game.charge>=100);ult.disabled=game.charge<100;}
function playTone(freq=440,duration=.08,type='sine',volume=.035){try{let ac=playTone.ac||(playTone.ac=new(window.AudioContext||window.webkitAudioContext)());if(ac.state==='suspended')ac.resume();let o=ac.createOscillator(),gain=ac.createGain();o.type=type;o.frequency.value=freq;gain.gain.setValueAtTime(volume,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(gain);gain.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
function makeFx(x,y,color,r=18,kind='ring',life=.38){effects.push({x,y,color,r,kind,t:0,life})}
function startAttack(){let s=statValues(),target=null,best=390;for(let e of enemies){let d=dist(e,player);if(d<best){best=d;target=e}}if(!target)return;let a=Math.atan2(target.y-player.y,target.x-player.x);player.angle=a;let twice=Math.random()<game.upgradeKeys.double;let n=twice?2:1;for(let i=0;i<n;i++){let spread=(i-(n-1)/2)*.08,ang=a+spread;shots.push({x:player.x+Math.cos(ang)*15,y:player.y+Math.sin(ang)*15,vx:Math.cos(ang)*500,vy:Math.sin(ang)*500,damage:s.dmg,life:.72,pierce:game.upgradeKeys.pierce||0,hit:[],color:characters[game.index].accent,type:characters[game.index].type})}game.attacks++;makeFx(player.x+Math.cos(a)*20,player.y+Math.sin(a)*20,characters[game.index].accent,8,'ring',.14);playTone(300+Math.random()*180,.045,'triangle',.015)}
function damageEnemy(e,amount,source='attack'){if(e.dead)return;let s=statValues(),g=game,near=enemies.filter(x=>!x.dead&&dist(x,player)<220).length;let mult=1;if(e.boss)mult+=g.upgradeKeys.bossDamage||0;if(near<5)mult+=g.upgradeKeys.focus||0;if(player.hp/player.maxHp<.25)mult+=g.upgradeKeys.lastStand||0;if(e.hp/e.maxHp<.3)mult+=g.upgradeKeys.execution||0;if(source==='ult'){mult*=s.ultDamage;if(player.hp/player.maxHp<.3)mult*=1+(g.upgradeKeys.finalFury||0);amount+=g.upgradeKeys.ultFlat||0}let crit=Math.random()<s.crit;if(crit)mult*=s.cdamage;e.hp-=amount*mult;e.flash=.1;g.charge=Math.min(g.chargeMax,g.charge+amount*.12*s.chargeSpeed);if(source==='ult')makeFx(e.x,e.y,'#e6f4a1',e.size*1.6,'burst',.32);else makeFx(e.x,e.y,crit?'#fff39a':characters[g.index].accent,crit?14:7,'spark',.18);if(e.hp<=0)killEnemy(e)}
function killEnemy(e){if(e.dead)return;e.dead=true;game.kills++;game.survivorCount++;game.charge=Math.min(game.chargeMax,game.charge+2.5*statValues().chargeSpeed);if(e.boss){game.charge=Math.min(game.chargeMax,game.charge+(game.upgradeKeys.bossCharge||0));game.adrenaline=5;makeFx(e.x,e.y,'#ffc16e',95,'burst',.7)}let xp=e.xp+(Math.random()<(game.upgradeKeys.treasure||0)?e.xp:0);for(let i=0;i<xp;i++)stones.push({x:e.x+rand(-14,14),y:e.y+rand(-14,14),value:1,bob:rand(0,6),vx:rand(-20,20),vy:rand(-20,20)});makeFx(e.x,e.y,e.color,e.size*1.8,'burst',.42);sparks.push({x:e.x,y:e.y,t:0,life:.35});game.xpTotal+=0;save.totalKills++;if(game.survivorCount%20===0&&game.upgradeKeys.survivor){player.hp=Math.min(statValues().hp,player.hp+1)}if(save.totalKills>=500&&!save.unlocked.includes(0)){save.unlocked.push(0);notify('Dusty has joined your roster!');persist()}if(e.boss&&game.upgradeKeys.bossCharge)game.charge=Math.min(game.chargeMax,game.charge+game.upgradeKeys.bossCharge);persist()}
function damagePlayer(amount,boss=false){if(game.invuln>0||game.ultState?.kind==='shell')return;if(Math.random()<(game.upgradeKeys.dodge||0)){makeFx(player.x,player.y,'#d7f5ff',25,'ring',.25);return}let reduction=statValues().reduction+(game.veteran>0?game.upgradeKeys.veteran||0:0);if(boss)reduction+=game.upgradeKeys.bossReduction||0;amount*=1-clamp(reduction,0,.85);if(game.shieldHp>0){let take=Math.min(game.shieldHp,amount);game.shieldHp-=take;amount-=take}if(amount<=0)return;player.hp-=amount;game.damageTimer=0;game.escape=3;if(game.upgradeKeys.quickRecovery)player.hp=Math.min(statValues().hp,player.hp);if(game.secondChance&&player.hp<=0){game.secondChance=false;player.hp=1;game.invuln=2;makeFx(player.x,player.y,'#fff2a1',90,'ring',.6);notify('SECOND CHANCE — keep moving!')}makeFx(player.x,player.y,'#ff746f',26,'burst',.25);playTone(120,.12,'sawtooth',.035);if(player.hp<=0)endRun()}
function spawnEnemy(){if(enemies.length>95)return;let t=game.time,w=game.wave,angle=rand(0,Math.PI*2),radius=Math.max(W,H)*.65+rand(40,150),base;if(t>28&&Math.random()<Math.min(.09,.012+game.wave*.003))base=enemyTypes[4];else{let r=Math.random();base=r<.47?enemyTypes[0]:r<.69?enemyTypes[1]:r<.87?enemyTypes[3]:enemyTypes[2]}let scale=1+(w-1)*.14;enemies.push({x:player.x+Math.cos(angle)*radius,y:player.y+Math.sin(angle)*radius,kind:base.kind,color:base.color,size:base.size,hp:base.hp*scale,maxHp:base.hp*scale,speed:base.speed*(1+Math.min(.45,(w-1)*.025)),damage:base.damage*(1+(w-1)*.08),xp:base.xp,boss:!!base.boss,attack:rand(.8,2),slow:0,web:0,flash:0,angle:0,dead:false})}
function damagePlayerProjectile(p){if(dist(p,player)<16){damagePlayer(p.damage,false);p.dead=true}}
function fireEnemyShot(e){let a=Math.atan2(player.y-e.y,player.x-e.x),v=125+game.wave*2;enemyShots.push({x:e.x,y:e.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,damage:e.damage,life:3,color:e.color,dead:false})}
function updateCombat(dt){let s=statValues(),g=game;g.attackTimer-=dt;if(g.attackTimer<=0){startAttack();g.attackTimer+=1/s.atk}for(let p of shots){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;for(let e of enemies){if(e.dead||p.hit.includes(e)||dist(p,e)>e.size+7)continue;let damage=p.damage;if(Math.random()<s.crit)damage*=s.cdamage;let before=e.hp;damageEnemy(e,damage);if(g.attacks%10===0&&g.upgradeKeys.explosive){for(let other of enemies)if(!other.dead&&other!==e&&dist(other,e)<62)damageEnemy(other,g.upgradeKeys.explosive)}p.hit.push(e);if(p.pierce>0)p.pierce--;else p.life=0;break}}shots=shots.filter(p=>p.life>0);for(let e of enemies){if(e.dead)continue;e.attack-=dt;e.flash=Math.max(0,e.flash-dt);if(e.web>0){e.web-=dt;continue}let d=dist(e,player),a=Math.atan2(player.y-e.y,player.x-e.x);e.angle=a;if(e.kind==='spitter'){if(d>135){e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt}else if(d<95){e.x-=Math.cos(a)*e.speed*.6*dt;e.y-=Math.sin(a)*e.speed*.6*dt}if(e.attack<=0&&d<330){fireEnemyShot(e);e.attack=2.2}}else if(d>e.size+16){e.x+=Math.cos(a)*e.speed*(e.slow>0?.35:1)*dt;e.y+=Math.sin(a)*e.speed*(e.slow>0?.35:1)*dt}else if(e.attack<=0){damagePlayer(e.damage,e.boss);e.attack=e.boss?1.15:1.55}if(e.slow>0)e.slow-=dt}enemies=enemies.filter(e=>!e.dead);for(let p of enemyShots){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(dist(p,player)<15)damagePlayer(p.damage,false),p.life=0}enemyShots=enemyShots.filter(p=>p.life>0)}

