function updateUltimate(dt){let u=game.ultState;if(!u)return;u.time-=dt;u.tick=(u.tick||0)+dt;if(u.kind==='tornado'){for(let e of enemies)if(!e.dead&&dist(e,u)<u.radius){let a=Math.atan2(u.y-e.y,u.x-e.x),d=dist(e,u);e.x+=Math.cos(a)*Math.min(150,d*1.4)*dt;e.y+=Math.sin(a)*Math.min(150,d*1.4)*dt}if(u.tick>=.25){for(let e of enemies)if(!e.dead&&dist(e,u)<u.radius)damageEnemy(e,30,'ult');u.tick=0}}
 if(u.kind==='shell'&&u.tick>=.55){for(let e of enemies)if(!e.dead&&dist(e,player)<115*statValues().range)damageEnemy(e,22,'ult');u.tick=0}
 if(u.kind==='toxic'&&u.tick>=.35){for(let e of enemies)if(!e.dead&&dist(e,u)<u.radius){e.slow=Math.max(e.slow,.4);damageEnemy(e,14,'ult')}u.tick=0}
 if(u.kind==='pack'&&u.tick>=.45){for(let e of enemies.filter(e=>!e.dead).sort((a,b)=>dist(a,player)-dist(b,player)).slice(0,3))damageEnemy(e,36,'ult');u.tick=0}
 if(u.kind==='swarm'&&u.tick>=.32){for(let e of enemies.filter(e=>!e.dead).sort((a,b)=>dist(a,player)-dist(b,player)).slice(0,5))damageEnemy(e,19,'ult');u.tick=0}
 if(u.time<=0){if(u.kind==='shell')game.invuln=0;game.ultState=null}}
function collectStones(){let s=statValues(),radius=s.pickup,magnet=game.upgradeKeys.magnet||0;for(let p of stones){let d=dist(p,player),reach=Math.max(20,magnet);if(d<radius+70){let a=Math.atan2(player.y-p.y,player.x-p.x),pull=Math.min(380,90+(radius+70-d)*2);p.x+=Math.cos(a)*pull*.016;p.y+=Math.sin(a)*pull*.016}if(d<Math.max(radius*.2,reach)){game.xp+=p.value*(1+s.xp);game.xpTotal+=p.value;save.totalXp+=p.value;p.collected=true}}stones=stones.filter(p=>!p.collected);if(game.xp>=game.nextXp&&mode==='playing'){levelUp();updateHud()}}
function movePlayer(dt){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(touch.active){x=touch.dx;y=touch.dy}let mag=Math.hypot(x,y);if(mag>1){x/=mag;y/=mag}let s=statValues(),slow=player.slowTime>0?.55:1;player.x+=x*s.speed*slow*dt;player.y+=y*s.speed*slow*dt;if(mag>.08)player.angle=Math.atan2(y,x);player.moving=mag>.08;if(player.slowTime>0)player.slowTime=Math.max(0,player.slowTime-dt);if(game.escape>0)game.escape=Math.max(0,game.escape-dt);if(game.invuln>0)game.invuln=Math.max(0,game.invuln-dt);if(game.adrenaline>0)game.adrenaline=Math.max(0,game.adrenaline-dt);if(game.ghost>0)game.ghost=Math.max(0,game.ghost-dt);if(game.veteran>0)game.veteran=Math.max(0,game.veteran-dt);if(game.upgradeKeys.regen&&player.hp<statValues().hp)player.hp=Math.min(statValues().hp,player.hp+statValues().regen*dt);game.momentumTime+=dt;if(game.upgradeKeys.recharge){game.rechargeTimer+=dt;if(game.rechargeTimer>=10){let n=Math.floor(game.rechargeTimer/10);game.rechargeTimer-=n*10;game.charge=Math.min(game.chargeMax,game.charge+n*5)}}if(game.upgradeKeys.jump&&game.time>=game.nextJump){let e=enemies.filter(e=>!e.dead).sort((a,b)=>dist(a,player)-dist(b,player))[0];if(e&&dist(e,player)<100){let a=Math.atan2(player.y-e.y,player.x-e.x);player.x+=Math.cos(a)*110;player.y+=Math.sin(a)*110;makeFx(player.x,player.y,'#d8f3a0',42,'ring',.3)}game.nextJump=game.time+15}}
function progressRun(dt){game.time+=dt;game.wave=1+Math.floor(game.time/45);if(game.wave>1&&Math.floor((game.time-dt)/45)<game.wave-1){game.veteran=game.upgradeKeys.veteran?4:0;notify(`WAVE ${game.wave} — STAY SHARP`);playTone(540,.18,'triangle',.03)}if(game.time>=480&&!save.unlocked.includes(1)){save.unlocked.push(1);persist();notify('N1co has joined your roster!')}game.spawnTimer-=dt;let interval=Math.max(.34,1.35-game.time*.0016-(game.wave-1)*.07);if(game.spawnTimer<=0){spawnEnemy();game.spawnTimer+=interval}if(Math.floor(game.time/150)>Math.floor((game.time-dt)/150)){let t=enemyTypes[4],r=Math.max(W,H)*.65+60,a=rand(0,Math.PI*2),scale=1+(game.wave-1)*.14;enemies.push({x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,kind:t.kind,color:t.color,size:t.size,hp:t.hp*scale,maxHp:t.hp*scale,speed:t.speed,damage:t.damage*(1+(game.wave-1)*.08),xp:t.xp,boss:true,attack:1,slow:0,web:0,flash:0,angle:0,dead:false});notify('A mighty beast approaches!')}for(let p of stones){p.bob+=dt*3;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.04,dt);p.vy*=Math.pow(.04,dt)}updateCombat(dt);updateUltimate(dt);collectStones();if(mode!=='playing')return;movePlayer(dt);game.charge=Math.min(game.chargeMax,game.charge+dt*.7*statValues().chargeSpeed);updateHud()}

