function drawBackground(){ctx.fillStyle='#13211d';ctx.fillRect(0,0,W,H);let ox=player?((W/2-player.x)%64):0,oy=player?((H/2-player.y)%64):0;ctx.strokeStyle='#c1e6af0b';ctx.lineWidth=1;for(let x=ox;x<W;x+=64){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=oy;y<H;y+=64){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.fillStyle='#bbd29508';for(let i=0;i<36;i++){let x=((i*173+ox*2)%W+W)%W,y=((i*271+oy*2)%H+H)%H;ctx.beginPath();ctx.arc(x,y,1+(i%3),0,Math.PI*2);ctx.fill()}}
function worldPos(o){return{x:W/2+(o.x-player.x),y:H/2+(o.y-player.y)}}
function drawEnemy(e){let p=worldPos(e),r=e.size,fade=clamp(1-Math.max(Math.abs(p.x)-W/2,Math.abs(p.y)-H/2)/(Math.max(W,H)*.65),0,1);if(fade<=0)return;ctx.save();ctx.globalAlpha=fade;ctx.translate(p.x,p.y);if(e.boss){ctx.shadowColor=e.color;ctx.shadowBlur=22}ctx.fillStyle=e.flash>0?'#fff':e.color;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#17211e';ctx.beginPath();ctx.arc(-r*.28,-r*.12,Math.max(1,r*.11),0,7);ctx.arc(r*.28,-r*.12,Math.max(1,r*.11),0,7);ctx.fill();if(e.web>0){ctx.strokeStyle='#e3d2ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r+5,0,Math.PI*2);ctx.stroke()}if(e.boss||e.hp<e.maxHp){ctx.fillStyle='#09120f';ctx.fillRect(-r,-r-9,r*2,4);ctx.fillStyle=e.boss?'#ff8b86':'#d7e47e';ctx.fillRect(-r,-r-9,r*2*clamp(e.hp/e.maxHp,0,1),4)}if(e.boss){ctx.fillStyle='#ffe2a6';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('ELITE',0,-r-13)}ctx.restore()}
function drawPlayer(){let x=W/2,y=H/2,c=characters[game.index];ctx.save();ctx.translate(x,y);if(game.invuln>0&&Math.floor(game.time*14)%2)ctx.globalAlpha=.5;ctx.rotate(player.angle);ctx.fillStyle='#0006';ctx.beginPath();ctx.ellipse(0,13,16,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.fill();ctx.rotate(-player.angle);ctx.font='25px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(c.icon,0,-2);ctx.restore();let u=game.ultState;if(u){ctx.save();ctx.globalAlpha=.22+Math.sin(game.time*9)*.08;ctx.strokeStyle=({tornado:'#d7f6ff',shell:'#b2f3a5',toxic:'#b8ef61',pack:'#d9e8e4',swarm:'#ffe87a'})[u.kind]||'#e4edcc';ctx.lineWidth=3;ctx.beginPath();ctx.arc(W/2,H/2,u.radius||90,0,Math.PI*2);ctx.stroke();ctx.restore()}}
function drawWorld(){drawBackground();if(!player)return;for(let s of stones){let p=worldPos(s);if(p.x< -20||p.x>W+20||p.y< -20||p.y>H+20)continue;let bob=Math.sin(s.bob)*3;ctx.fillStyle='#b9f779';ctx.shadowColor='#9bea67';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(p.x,p.y-5-bob);ctx.lineTo(p.x+5,p.y-bob);ctx.lineTo(p.x,p.y+5-bob);ctx.lineTo(p.x-5,p.y-bob);ctx.closePath();ctx.fill();ctx.shadowBlur=0}for(let e of enemies)drawEnemy(e);for(let p of shots){let q=worldPos(p);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=9;ctx.beginPath();ctx.arc(q.x,q.y,4,0,Math.PI*2);ctx.fill()}for(let p of enemyShots){let q=worldPos(p);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=9;ctx.beginPath();ctx.arc(q.x,q.y,5,0,Math.PI*2);ctx.fill()}drawPlayer();for(let f of effects){f.t+=.016;let q=worldPos(f),k=f.t/f.life;ctx.save();ctx.globalAlpha=Math.max(0,1-k);ctx.strokeStyle=f.color;ctx.lineWidth=f.kind==='burst'?3:2;ctx.beginPath();ctx.arc(q.x,q.y,f.r*(.25+.9*k),0,Math.PI*2);ctx.stroke();if(f.kind==='web'){for(let a=0;a<8;a++){let ang=a*Math.PI/4;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x+Math.cos(ang)*f.r*k,q.y+Math.sin(ang)*f.r*k);ctx.stroke()}}ctx.restore()}effects=effects.filter(f=>f.t<f.life)}
