await page.locator('.character-tile').nth(2).click(); await page.click('#startRun');
console.log('HUD visible',await page.locator('#hud').isVisible(),'hero',await page.locator('#heroName').textContent());
await page.evaluate(()=>{ game.xp=game.nextXp; collectStones(); });
console.log('level overlay',await page.locator('#levelScreen').isVisible(),'cards',await page.locator('.upgrade-card').count());
console.log('stats', (await page.locator('#runStats').innerText()).slice(0,200));
await page.locator('.upgrade-card').first().click();
console.log('continued',await page.locator('#levelScreen').isVisible(),await page.locator('#level').innerText());
await page.evaluate(()=>{ mode='playing'; game.charge=100; updateHud(); activateUltimate(); });
console.log('ult',await page.locator('#ultButton').getAttribute('class'), 'state',await page.evaluate(()=>game.ultState?.kind||'instant'));
await page.evaluate(()=>damagePlayer(10000));
console.log('gameover',await page.locator('#gameOver').isVisible(),'summary',await page.locator('#runSummary').innerText());
console.log('errors',errors);
await browser.close();
EOF

