node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions});
const page = await browser.newPage({viewport:{width:1440,height:900}});
const errors=[]; page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://127.0.0.1:8765');
await page.click('#playBtn');
const tiles=await page.locator('.character-tile').count(), locked=await page.locator('.character-tile.locked').count();
await page.locator('.character-tile').nth(2).click(); await page.click('#startRun');
await page.evaluate(()=>{ game.xp=game.nextXp; collectStones(); });
const level=await page.locator('#levelScreen').isVisible(), cards=await page.locator('.upgrade-card').count();
await page.locator('.upgrade-card').first().click();
await page.evaluate(()=>{game.charge=100;activateUltimate();game.invuln=0;game.ultState=null;player.hp=1;damagePlayer(10000)});
const over=await page.locator('#gameOver').isVisible();
const summary=(await page.locator('#runSummary').innerText()).replace(/\n/g,' | ');
console.log(JSON.stringify({tiles,locked,level,cards,over,summary,errors},null,2));
await browser.close();
EOF

